#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdio.h>

#define MAX_TOKEN_LEN 63
#define INITIAL_BUF_SIZE 128

typedef struct {
    char *data;
    size_t len;
    size_t cap;
} dynamic_buf_t;

typedef struct {
    char token[MAX_TOKEN_LEN + 1];
    int token_type;
    size_t source_offset;
} parsed_token_t;

typedef struct {
    parsed_token_t *tokens;
    size_t count;
    size_t capacity;
} token_list_t;

/* Returns the number of bytes in a UTF-8 sequence given the lead byte.
 * Returns 0 for invalid lead bytes. */
static int utf8_seq_len(unsigned char lead) {
    if (lead < 0x80) return 1;
    if ((lead & 0xE0) == 0xC0) return 2;
    if ((lead & 0xF0) == 0xE0) return 3;
    if ((lead & 0xF8) == 0xF0) return 4;
    return 0; /* invalid */
}

/* Validates that continuation bytes are well-formed.
 * Returns 1 if valid, 0 if invalid. */
static int validate_continuation(const unsigned char *buf, int seq_len, size_t remaining) {
    if ((size_t)seq_len > remaining) return 0;
    for (int i = 1; i < seq_len; i++) {
        if ((buf[i] & 0xC0) != 0x80) return 0;
    }
    return 1;
}

/* Normalize a UTF-8 token: strip invalid sequences, copy valid ones.
 * Output buffer must be at least (input_len + 1) bytes.
 * Returns length of normalized output (not counting NUL). */
static size_t normalize_utf8_token(const char *input, size_t input_len,
                                    char *output, size_t output_cap) {
    size_t in_pos = 0, out_pos = 0;

    while (in_pos < input_len) {
        unsigned char ch = (unsigned char)input[in_pos];
        int seq_len = utf8_seq_len(ch);

        if (seq_len == 0) {
            /* Skip invalid lead byte */
            in_pos++;
            continue;
        }

        size_t remaining = input_len - in_pos;
        if (!validate_continuation((const unsigned char *)&input[in_pos],
                                    seq_len, remaining)) {
            /* Skip this byte, try next */
            in_pos++;
            continue;
        }

        /* Check if we have room in output buffer.
         * We need seq_len bytes plus the NUL terminator. */
        if (out_pos + seq_len <= output_cap) {  /* BUG: should be < output_cap or out_pos + seq_len + 1 <= output_cap */
            memcpy(&output[out_pos], &input[in_pos], seq_len);
            out_pos += seq_len;
        }

        in_pos += seq_len;
    }

    /* NUL-terminate */
    if (out_pos < output_cap) {
        output[out_pos] = '\0';
    } else {
        output[output_cap - 1] = '\0';
    }

    return out_pos;
}

static int buf_ensure_capacity(dynamic_buf_t *buf, size_t needed) {
    if (needed <= buf->cap) return 0;
    size_t new_cap = buf->cap * 2;
    if (new_cap < needed) new_cap = needed;
    char *new_data = realloc(buf->data, new_cap);
    if (!new_data) return -1;
    buf->data = new_data;
    buf->cap = new_cap;
    return 0;
}

static int is_token_char(unsigned char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
           (c >= '0' && c <= '9') || c == '_' || c >= 0x80;
}

/* Tokenize input, normalizing UTF-8 in each token */
token_list_t *tokenize_input(const char *input, size_t input_len) {
    token_list_t *list = calloc(1, sizeof(token_list_t));
    if (!list) return NULL;

    list->capacity = 16;
    list->tokens = calloc(list->capacity, sizeof(parsed_token_t));
    if (!list->tokens) { free(list); return NULL; }

    size_t pos = 0;
    while (pos < input_len) {
        /* Skip whitespace/delimiters */
        while (pos < input_len && !is_token_char((unsigned char)input[pos])) {
            pos++;
        }
        if (pos >= input_len) break;

        /* Find token end */
        size_t token_start = pos;
        while (pos < input_len && is_token_char((unsigned char)input[pos])) {
            pos++;
        }
        size_t token_len = pos - token_start;

        /* Allocate normalization buffer: token_len + 1 for NUL */
        size_t norm_buf_size = token_len + 1;
        char *norm_buf = malloc(norm_buf_size);
        if (!norm_buf) continue;

        /* Normalize the token's UTF-8 content */
        size_t norm_len = normalize_utf8_token(&input[token_start], token_len,
                                               norm_buf, norm_buf_size);

        /* Truncate to MAX_TOKEN_LEN */
        if (norm_len > MAX_TOKEN_LEN) {
            norm_len = MAX_TOKEN_LEN;
            norm_buf[norm_len] = '\0';
        }

        /* Add to token list */
        if (list->count >= list->capacity) {
            size_t new_cap = list->capacity * 2;
            parsed_token_t *new_tokens = realloc(list->tokens,
                                                  new_cap * sizeof(parsed_token_t));
            if (!new_tokens) { free(norm_buf); continue; }
            list->tokens = new_tokens;
            list->capacity = new_cap;
        }

        parsed_token_t *tok = &list->tokens[list->count];
        memset(tok, 0, sizeof(*tok));
        memcpy(tok->token, norm_buf, norm_len + 1);
        tok->token_type = (norm_len > 0 && (unsigned char)norm_buf[0] >= 0x80) ? 2 : 1;
        tok->source_offset = token_start;
        list->count++;

        free(norm_buf);
    }

    return list;
}

void free_token_list(token_list_t *list) {
    if (list) {
        free(list->tokens);
        free(list);
    }
}

/* Process input and return concatenated normalized tokens */
char *process_document(const char *input, size_t input_len, size_t *out_len) {
    token_list_t *tokens = tokenize_input(input, input_len);
    if (!tokens) return NULL;

    dynamic_buf_t result = {0};
    result.data = malloc(INITIAL_BUF_SIZE);
    if (!result.data) { free_token_list(tokens); return NULL; }
    result.cap = INITIAL_BUF_SIZE;
    result.len = 0;

    for (size_t i = 0; i < tokens->count; i++) {
        size_t tlen = strlen(tokens->tokens[i].token);
        size_t needed = result.len + tlen + 2; /* space + token + potential NUL */

        if (buf_ensure_capacity(&result, needed) != 0) continue;

        if (result.len > 0) {
            result.data[result.len++] = ' ';
        }
        memcpy(&result.data[result.len], tokens->tokens[i].token, tlen);
        result.len += tlen;
    }

    if (buf_ensure_capacity(&result, result.len + 1) != 0) {
        free(result.data);
        free_token_list(tokens);
        return NULL;
    }
    result.data[result.len] = '\0';

    free_token_list(tokens);
    if (out_len) *out_len = result.len;
    return result.data;
}
